n_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "577252cd-facc-5b4e-82c4-74eb58fe7ede"}, {"title": "李厚领十旗击汴兵失利", "start_year": null, "end_year": null, "time_original": "汴兵攻寿州时；确年待考", "dynasty": "唐", "description": "朱延寿规定军中每旗二十五骑，命黑云队长李厚领十旗击汴兵，未胜。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "dde9c34a-0066-5e34-aee0-f1cb2ad1a2a8"}, {"title": "朱延寿欲斩李厚，柴再用助请增兵", "start_year": null, "end_year": null, "time_original": "李厚首战不胜以后；确年待考", "dynasty": "唐", "description": "朱延寿欲斩李厚。李厚称众寡不敌，愿加兵再战，败则死；都押牙柴再用也替他求情，朱延寿增给五旗。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b1905a37-4e87-5a9b-bd85-a7df7d08ebaf"}, {"title": "李厚再战、柴再用助，朱延寿乘胜败汴兵", "start_year": null, "end_year": null, "time_original": "增五旗以后；确年待考", "dynasty": "唐", "description": "李厚殊死再战，柴再用相助，朱延寿尽众乘势进击，汴军败走。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f5bea48f-1b9a-540c-8fe3-0bd8339df5b6"}, {"title": "杨行密另遣兵袭取涟水", "start_year": null, "end_year": null, "time_original": "寿州战事后本段另记；确年待考", "dynasty": "唐", "description": "杨行密另派兵袭击涟水，攻下该地。", "phases": [], "location_name": "涟水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e4547330-d096-5ff6-a57a-a287b22f8133"}, {"title": "钱镠表董昌僭逆不可赦，请本道兵讨", "start_year": 895, "end_year": 895, "time_original": "895年四月朝廷释董昌以后；确日未载", "dynasty": "唐", "description": "钱镠上表认为董昌僭逆不可赦，请以本道军队讨伐。", "phases": [], "location_name": "朝廷、浙西", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7c6f4d75-e760-536b-b754-ff2df65431f1"}, {"title": "韦昭度以太保致仕", "start_year": 895, "end_year": 895, "time_original": "895年四月条；确日未载", "dynasty": "唐", "description": "太傅、门下侍郎、同平章事韦昭度以太保致仕。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "394f3090-d817-569e-9630-12883de72df7"}, {"title": "刘建锋授武安节度使", "start_year": 895, "end_year": 895, "time_original": "895年四月戊戌", "dynasty": "唐", "description": "朝廷以刘建锋为武安节度使。", "phases": [], "location_name": "武安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "01b429bc-da93-5b67-891f-9626756870c6"}, {"title": "刘建锋以马殷为内外马步军都指挥使", "start_year": 895, "end_year": 895, "time_original": "895年刘建锋受武安节度使条；确日未另载", "dynasty": "唐", "description": "刘建锋任命马殷为内外马步军都指挥使。", "phases": [], "location_name": "武安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "eb70721f-c11f-5879-86bb-8b5b0f54280c"}, {"title": "杨行密遣使劝钱镠释董昌", "start_year": 895, "end_year": 895, "time_original": "895年四月条；确日未载", "dynasty": "唐", "description": "杨行密遣使到钱镠处，声称董昌已改过、应释放其责。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "280e26f8-093d-59c4-882e-23ed76d64968"}, {"title": "杨行密另遣使促董昌朝贡", "start_year": 895, "end_year": 895, "time_original": "895年四月条；确日未载", "dynasty": "唐", "description": "杨行密又派使者到董昌处，催促其向朝廷朝贡。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "7d21ce80-551d-5160-bd8a-1581e8fa9cd6"}]'::jsonb)
